package com.rezoxnemesis.videostudio;

import android.app.*;
import android.content.Context;
import android.graphics.*;
import android.os.Bundle;
import android.widget.*;
import org.json.*;
import java.io.File;
import java.util.UUID;
import java.util.concurrent.*;
import java.util.function.Consumer;

/** Detached mesh draft. Preparation is read-only; Apply uses the ordinary undoable edit. */
final class SketchPaintMeshDialog implements AutoCloseable {
    interface Backend{JSONObject prepare(Context context,JSONObject request)throws Exception;JSONObject edit(Context context,JSONObject request)throws Exception;Bitmap load(Context context,JSONObject document,JSONObject image,JSONObject patch)throws Exception;}
    private final Activity activity;
    private final JSONObject opened,image;
    private final String objectId;
    private final int frame;
    private final Consumer<JSONObject> applied;
    private final Backend backend;
    private final ExecutorService worker;
    private final LinearLayout form;
    private final SketchPaintMeshViewport viewport;
    private final TextView status;
    private final EditText columns,rows,vertexX,vertexY,keyFrame;
    private final SeekBar vertex;
    private final Button prepare,apply,setVertex,setKey,deleteKey;
    private AlertDialog dialog;
    private JSONObject patch,mesh,displayMesh,pendingApply;
    private CheckBox editKeyPose,focusToInk;
    private boolean keyDirty;
    private Bitmap bitmap,focusedBitmap;
    private boolean closed,busy,reported,committing;
    private int generation;
    static SketchPaintMeshDialog show(Activity activity,JSONObject document,String objectId,int frame,Consumer<JSONObject> applied)throws Exception{
        SketchPaintMeshDialog owner=new SketchPaintMeshDialog(activity,document,objectId,frame,applied,new Backend(){public JSONObject prepare(Context c,JSONObject request)throws Exception{return SketchPaintMeshPrepare.prepare(c,request);}public JSONObject edit(Context c,JSONObject request)throws Exception{return SketchEditOps.execute(c,"sketch_edit",request);}public Bitmap load(Context c,JSONObject document,JSONObject image,JSONObject patch)throws Exception{return loadTexture(c,document,image,patch);}},Executors.newSingleThreadExecutor());owner.open();return owner;
    }
    SketchPaintMeshDialog(Activity activity,JSONObject document,String objectId,int frame,Consumer<JSONObject> applied,Backend backend,ExecutorService worker)throws Exception{
        this.activity=activity;opened=SketchDocument.copy(document);image=SketchDocument.copy(SketchDocument.object(opened,objectId));this.objectId=objectId;this.frame=frame;this.applied=applied;this.backend=backend;this.worker=worker;
        if(!"paint".equals(image.getString("kind")))throw SketchDocument.bad("Select an owned paint cel to prepare its deformation grid");
        if(frame<0||frame>=opened.getInt("frameCount"))throw SketchDocument.bad("Choose a frame inside the drawing");
        form=new LinearLayout(activity);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(16),dp(8),dp(16),dp(12));
        text("Prepare an editable grid for this paint cel. Drag a grid vertex or enter its local coordinates. Apply saves one ordinary edit; Undo restores the previous paint.");
        status=text("Prepare grid to inspect the source and its editable vertices.");status.setContentDescription("Paint mesh status");
        columns=input("Grid columns (1–16)","4");rows=input("Grid rows (1–16)","4");focusToInk=new CheckBox(activity);focusToInk.setText("Focus grid on retained paint");focusToInk.setContentDescription("Focus grid on retained paint");form.addView(focusToInk);prepare=button("Prepare grid",this::prepare);
        viewport=new SketchPaintMeshViewport(activity);JSONObject localBounds=image.getJSONObject("bounds");viewport.setLocalSize((float)(localBounds.getDouble("width")*opened.getInt("width")),(float)(localBounds.getDouble("height")*opened.getInt("height")));viewport.setContentDescription("Paint mesh viewport");form.addView(viewport,new LinearLayout.LayoutParams(-1,dp(300)));
        button("Zoom in",()->viewport.zoomIn());button("Zoom out",()->viewport.zoomOut());button("Fit paint",()->viewport.fit());button("Fit grid",()->viewport.fitGrid());
        CheckBox pan=new CheckBox(activity);pan.setText("Pan paint");pan.setContentDescription("Pan paint grid");form.addView(pan);pan.setOnCheckedChangeListener((b,v)->viewport.setPanMode(v));
        CheckBox grid=new CheckBox(activity);grid.setText("Show grid");grid.setChecked(true);grid.setContentDescription("Show paint grid");form.addView(grid);grid.setOnCheckedChangeListener((b,v)->viewport.setGridVisible(v));
        Spinner backdrop=new Spinner(activity);backdrop.setContentDescription("Mesh preview background");backdrop.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,new String[]{"Checkerboard","Dark","Light"}));form.addView(backdrop);backdrop.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int at,long id){viewport.setBackdrop(at);}});
        vertex=new SeekBar(activity);vertex.setContentDescription("Mesh vertex");form.addView(vertex);vertexX=input("Vertex local X (-4..4)","0");vertexY=input("Vertex local Y (-4..4)","0");
        setVertex=button("Update vertex",()->{int at=vertex.getProgress();pendingApply=null;displayMesh.getJSONArray("points").put(at,new JSONArray().put(number(vertexX,-4,4)).put(number(vertexY,-4,4)));keyDirty=editKeyPose.isChecked();sync();viewport.invalidate();status.setText("Vertex updated in this draft. Apply saves the grid.");});
        keyFrame=input("Mesh key frame (1 based)",String.valueOf(frame+1));
        editKeyPose=new CheckBox(activity);editKeyPose.setText("Edit mesh key pose");editKeyPose.setContentDescription("Edit mesh key pose");form.addView(editKeyPose);editKeyPose.setOnCheckedChangeListener((b,v)->{try{selectPose();}catch(Exception failure){message(failure);}});
        button("Load selected mesh pose",()->selectPose());
        setKey=button("Set mesh key",()->{pendingApply=null;int position=integer(keyFrame,1,opened.getInt("frameCount"))-1;JSONArray keys=mesh.getJSONArray("keys");int at=-1;for(int i=0;i<keys.length();i++)if(keys.getJSONObject(i).getInt("frame")==position)at=i;if(at<0&&keys.length()>=1200)throw SketchDocument.bad("At most 1200 mesh keys");JSONObject key=new JSONObject().put("frame",position).put("points",new JSONArray(displayMesh.getJSONArray("points").toString())).put("interpolation","linear");if(at>=0)keys.put(at,key);else keys.put(key);sortKeys(keys);keyDirty=false;sync();status.setText("Mesh key prepared at frame "+(position+1)+". Apply saves the keys.");});
        deleteKey=button("Remove mesh key",()->{pendingApply=null;int position=integer(keyFrame,1,opened.getInt("frameCount"))-1;JSONArray keys=mesh.getJSONArray("keys");for(int i=keys.length()-1;i>=0;i--)if(keys.getJSONObject(i).getInt("frame")==position)keys.remove(i);keyDirty=false;sync();status.setText("Mesh key removed from this draft.");});
        text("The grid uses the paint source's local coordinates; ordinary object transforms stay separate. Source pixels and export resolution are retained. Grid keys follow the drawing's existing frame clock.");
        apply=button("Apply grid",this::apply);
        button("Remove grid",()->{if(!image.has("paintMesh"))throw SketchDocument.bad("This source paint has no saved grid");pendingApply=new JSONObject().put("sketchId",opened.getString("id")).put("expectedRevision",opened.getLong("revision")).put("operationId","paint_grid_remove_"+UUID.randomUUID().toString().replace("-","")).put("operations",new JSONArray().put(new JSONObject().put("type","update_object").put("objectId",objectId).put("patch",new JSONObject().put("paintMesh",JSONObject.NULL))));apply();});
        vertex.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int at,boolean human){adoptVertex(at);}public void onStartTrackingTouch(SeekBar bar){}public void onStopTrackingTouch(SeekBar bar){}});
        viewport.setCallbacks(()->{pendingApply=null;keyDirty=editKeyPose.isChecked();sync();adoptVertex(vertex.getProgress());status.setText("Vertex moved in the draft. Apply validates and saves the grid.");},at->{vertex.setProgress(at);adoptVertex(at);});focusToInk.setOnCheckedChangeListener((b,v)->{pendingApply=null;patch=null;mesh=null;displayMesh=null;viewport.setMesh(null);status.setText("Grid focus changed. Prepare again before Apply.");sync();});sync();
    }
    void open(){ScrollView scroll=new ScrollView(activity);scroll.addView(form);dialog=new AlertDialog.Builder(activity).setTitle("Paint deformation grid").setView(scroll).setNegativeButton("Close",(d,w)->close()).create();dialog.setOnDismissListener(d->close());dialog.show();activity.getApplication().registerActivityLifecycleCallbacks(lifecycle);if(image.has("paintMesh"))try{focusToInk.setChecked(image.getJSONObject("paintMesh").has("sourceRect"));patch=new JSONObject().put("paintMesh",SketchDocument.copy(image.getJSONObject("paintMesh")));mesh=patch.getJSONObject("paintMesh");columns.setText(String.valueOf(mesh.getInt("columns")));rows.setText(String.valueOf(mesh.getInt("rows")));loadExisting();}catch(Exception error){message(error);}}
    private void prepare()throws Exception{final JSONObject request=new JSONObject().put("sketchId",opened.getString("id")).put("expectedRevision",opened.getLong("revision")).put("objectId",objectId).put("columns",integer(columns,1,16)).put("rows",integer(rows,1,16));if(focusToInk.isChecked())request.put("focusToInk",true);submitLoad(request);}
    private void loadExisting()throws Exception{submitLoad(null);}
    private void submitLoad(JSONObject request)throws Exception{pendingApply=null;busy=true;sync();status.setText("Validating and decoding the owned paint off the UI thread…");final int token=++generation;worker.execute(()->{Bitmap loaded=null,loadedFocus=null;try{JSONObject prepared=patch;if(request!=null){JSONObject reply=backend.prepare(activity.getApplicationContext(),request);if(reply.getBoolean("sourceModified")||reply.getLong("sourceRevision")!=opened.getLong("revision")||!opened.getString("id").equals(reply.getString("sketchId"))||!objectId.equals(reply.getString("objectId"))||!image.getJSONObject("paint").getString("sha256").equals(reply.getString("sourcePaintSha256")))throw SketchDocument.bad("Prepared grid belongs to another image revision");JSONObject operation=reply.getJSONObject("operation");if(!"update_object".equals(operation.getString("type"))||!objectId.equals(operation.getString("objectId")))throw SketchDocument.bad("Prepared grid operation rejected");prepared=SketchDocument.copy(operation.getJSONObject("patch"));}
            loaded=backend.load(activity.getApplicationContext(),opened,image,prepared);if(loaded==null||loaded.isRecycled()||loaded.getWidth()!=opened.getInt("width")||loaded.getHeight()!=opened.getInt("height"))throw SketchDocument.bad("Paint grid preview dimensions differ from its source");JSONObject draft=SketchDocument.copy(image).put("paintMesh",prepared.getJSONObject("paintMesh"));SketchPaintMesh.validate(draft,opened.getInt("frameCount"));if(draft.getJSONObject("paintMesh").has("sourceRect"))SketchPaintMeshPrepare.requireSupport(draft,SketchPaintMeshPrepare.supportRectangle(loaded));if(draft.getJSONObject("paintMesh").has("sourceRect"))loadedFocus=SketchPaintMesh.focusedTexture(loaded,draft.getJSONObject("paintMesh"),0);final Bitmap done=loaded,doneFocus=loadedFocus;final JSONObject accepted=prepared;activity.runOnUiThread(()->{busy=false;if(unavailable()||token!=generation){done.recycle();if(doneFocus!=null)doneFocus.recycle();return;}if(bitmap!=null)bitmap.recycle();if(focusedBitmap!=null)focusedBitmap.recycle();bitmap=done;focusedBitmap=doneFocus;patch=accepted;mesh=patch.optJSONObject("paintMesh");viewport.setBitmap(bitmap);viewport.setFocusedBitmap(focusedBitmap);displayMesh=mesh;viewport.setMesh(displayMesh);if(mesh.has("sourceRect"))viewport.post(()->viewport.fitGrid());vertex.setMax(mesh.optJSONArray("points").length()-1);vertex.setProgress(0);adoptVertex(0);status.setText("Grid draft ready. Drag or enter vertex coordinates; Apply saves with Undo.");sync();});
        }catch(Exception|OutOfMemoryError failure){if(loaded!=null)loaded.recycle();if(loadedFocus!=null)loadedFocus.recycle();activity.runOnUiThread(()->{busy=false;if(unavailable()||token!=generation)return;message(failure);sync();});}});}
    private void apply()throws Exception{if(pendingApply==null)pendingApply=new JSONObject().put("sketchId",opened.getString("id")).put("expectedRevision",opened.getLong("revision")).put("operationId","paint_mesh_"+UUID.randomUUID().toString().replace("-","" )).put("operations",new JSONArray().put(new JSONObject().put("type","update_object").put("objectId",objectId).put("patch",SketchDocument.copy(patch))));final JSONObject request=SketchDocument.copy(pendingApply);busy=committing=true;sync();status.setText("Validating and saving the native grid…");worker.execute(()->{try{JSONObject receipt=backend.edit(activity.getApplicationContext(),request);if(!receipt.optBoolean("persisted")||!opened.getString("id").equals(receipt.getString("sketchId")))throw SketchDocument.bad("Grid save did not confirm this drawing");activity.runOnUiThread(()->{busy=committing=false;if(!reported&&!activity.isDestroyed()&&!activity.isFinishing()){reported=true;applied.accept(receipt);}close();});}catch(Exception|OutOfMemoryError failure){activity.runOnUiThread(()->{busy=committing=false;if(unavailable())return;message(failure);sync();});}});}
    private void selectPose()throws Exception{if(mesh==null)return;if(editKeyPose.isChecked()){int at=integer(keyFrame,1,opened.getInt("frameCount"))-1;JSONObject item=SketchDocument.copy(image);item.put("paintMesh",mesh);displayMesh=SketchDocument.copy(mesh);displayMesh.put("points",SketchPaintMesh.pointsAt(item,at));}else displayMesh=mesh;keyDirty=false;viewport.setMesh(displayMesh);adoptVertex(vertex.getProgress());sync();}
    private void adoptVertex(int at){if(displayMesh==null)return;try{JSONArray point=displayMesh.getJSONArray("points").getJSONArray(at);vertexX.setText(String.valueOf(point.getDouble(0)));vertexY.setText(String.valueOf(point.getDouble(1)));viewport.selectVertex(at);}catch(Exception invalid){message(invalid);}}
    private void sync(){boolean edit=!closed&&!busy;prepare.setEnabled(edit&&!image.has("paintMesh"));focusToInk.setEnabled(edit&&!image.has("paintMesh"));columns.setEnabled(edit&&!image.has("paintMesh"));rows.setEnabled(edit&&!image.has("paintMesh"));boolean ready=edit&&mesh!=null&&bitmap!=null;apply.setEnabled(ready&&!keyDirty);editKeyPose.setEnabled(ready);setVertex.setEnabled(ready);setKey.setEnabled(ready);deleteKey.setEnabled(ready);viewport.setEnabled(ready);vertex.setEnabled(ready);vertexX.setEnabled(ready);vertexY.setEnabled(ready);keyFrame.setEnabled(ready);}
    private static void sortKeys(JSONArray keys)throws Exception{java.util.List<JSONObject> values=new java.util.ArrayList<>();for(int i=0;i<keys.length();i++)values.add(keys.getJSONObject(i));values.sort(java.util.Comparator.comparingInt(v->v.optInt("frame")));for(int i=0;i<values.size();i++)keys.put(i,values.get(i));}
    private boolean unavailable(){return closed||activity.isDestroyed()||activity.isFinishing();}
    private void message(Throwable failure){status.setText("Grid draft retained: "+failure.getMessage());}
    @Override public void close(){if(closed)return;closed=true;++generation;viewport.setBitmap(null);viewport.setFocusedBitmap(null);if(focusedBitmap!=null){focusedBitmap.recycle();focusedBitmap=null;}if(bitmap!=null){bitmap.recycle();bitmap=null;}if(committing)worker.shutdown();else worker.shutdownNow();activity.getApplication().unregisterActivityLifecycleCallbacks(lifecycle);if(dialog!=null&&dialog.isShowing())dialog.dismiss();}
    private final Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){if(a==activity)close();}};
    private interface Action{void run()throws Exception;}
    private int dp(int value){return StudioUi.dp(activity,value);}
    private TextView text(String value){TextView view=new TextView(activity);view.setText(value);form.addView(view);return view;}
    private EditText input(String label,String value){text(label);EditText view=new EditText(activity);view.setSingleLine(true);view.setContentDescription(label);view.setText(value);form.addView(view);return view;}
    private Button button(String label,Action action){Button view=new Button(activity);view.setText(label);form.addView(view);view.setOnClickListener(v->{if(busy||closed)return;try{action.run();}catch(Exception failure){message(failure);}});return view;}
    private static int integer(EditText view,int min,int max)throws Exception{String value=view.getText().toString().trim();if(!value.matches("[0-9]+"))throw SketchDocument.bad("Enter a whole number from "+min+" to "+max);int parsed=Integer.parseInt(value);if(parsed<min||parsed>max)throw SketchDocument.bad("Enter a whole number from "+min+" to "+max);return parsed;}
    private static double number(EditText view,double min,double max)throws Exception{double value=Double.parseDouble(view.getText().toString());if(!Double.isFinite(value)||value<min||value>max)throw SketchDocument.bad("Vertex coordinates must be -4..4");return value;}
    private static Bitmap loadTexture(Context context,JSONObject document,JSONObject image,JSONObject patch)throws Exception{return SketchPaintMeshPrepare.texture(context,document,image);}
}
